function launch_container() {
    docker run -it --entrypoint="" -e POETRY_HTTP_BASIC_JFROG_PASSWORD=${POETRY_HTTP_BASIC_JFROG_PASSWORD} -e POETRY_HTTP_BASIC_JFROG_USERNAME=${POETRY_HTTP_BASIC_JFROG_USERNAME} -e POETRY_HTTP_BASIC_ARTIFACTORY_PASSWORD=${POETRY_HTTP_BASIC_ARTIFACTORY_PASSWORD} -e POETRY_HTTP_BASIC_ARTIFACTORY_USERNAME=${POETRY_HTTP_BASIC_ARTIFACTORY_USERNAME} -e BUNDLE_RAMSEYSOLUTIONS__JFROG__IO=$BUNDLE_RAMSEYSOLUTIONS__JFROG__IO -e ARTIFACTORY_TOKEN=$ARTIFACTORY_TOKEN -e ARTIFACTORY_USERNAME=$ARTIFACTORY_USERNAME -v $PWD:/app -v $HOME/.npmrc:/root/.npmrc -v $HOME/.aws:/root/.aws -w /app $1 bash
}
